<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Device\Application;

use DateInterval;
use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Device\Domain\DeviceAuthorization;
use Civi\Lughauth\Features\OAuth\Device\Domain\DeviceAuthorizationStatus;
use Civi\Lughauth\Features\OAuth\Device\Domain\DeviceAuthorizationGrantType;
use Civi\Lughauth\Features\OAuth\Device\Domain\Gateway\DeviceAuthorizationGateway;
use Civi\Lughauth\Features\OAuth\Device\Domain\Exception\DeviceAuthorizationException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;

final class DeviceAuthorizationService
{
    public const int DEFAULT_INTERVAL = 5;
    public const string DEFAULT_TTL = 'PT10M';

    public function __construct(private readonly DeviceAuthorizationGateway $gateway)
    {
    }

    public function createAuthorization(
        string $tenant,
        ClientData $client,
        string $scope,
        array $audiences
    ): DeviceAuthorization {
        $now = new DateTimeImmutable();
        $expires = $now->add(new DateInterval(self::DEFAULT_TTL));
        $deviceCode = Random::uuid();
        $userCode = $this->generateUserCode($tenant);
        $authorization = new DeviceAuthorization(
            deviceCode: $deviceCode,
            userCode: $userCode,
            tenant: $tenant,
            clientId: $client->id,
            scope: $scope,
            audiences: $audiences,
            interval: self::DEFAULT_INTERVAL,
            requestedAt: $now,
            expiresAt: $expires,
            status: DeviceAuthorizationStatus::PENDING,
            auth: null,
            lastPollAt: null
        );
        $this->gateway->create($authorization);
        return $authorization;
    }

    public function findByUserCode(string $tenant, string $userCode): ?DeviceAuthorization
    {
        return $this->gateway->findByUserCode($tenant, $userCode);
    }

    public function findByDeviceCode(string $deviceCode): ?DeviceAuthorization
    {
        return $this->gateway->findByDeviceCode($deviceCode);
    }

    public function approveByUserCode(string $tenant, string $userCode, AuthenticationResult $auth): bool
    {
        $record = $this->gateway->findByUserCode($tenant, $userCode);
        if ($record === null) {
            return false;
        }
        if ($record->isExpired(new DateTimeImmutable())) {
            return false;
        }
        if ($record->status !== DeviceAuthorizationStatus::PENDING) {
            return false;
        }
        return $this->gateway->approve($record->deviceCode, $auth);
    }

    public function exchangeDeviceCode(string $deviceCode): AuthenticationResult
    {
        if ($deviceCode === '') {
            throw DeviceAuthorizationException::invalidRequest('device_code is required');
        }
        $now = new DateTimeImmutable();
        $record = $this->gateway->findByDeviceCode($deviceCode);
        if ($record === null) {
            throw DeviceAuthorizationException::invalidGrant();
        }
        if ($record->isExpired($now)) {
            $this->gateway->consume($deviceCode);
            throw DeviceAuthorizationException::expiredToken();
        }
        if ($record->status === DeviceAuthorizationStatus::DENIED) {
            throw DeviceAuthorizationException::accessDenied();
        }
        if ($record->status === DeviceAuthorizationStatus::PENDING) {
            if ($record->lastPollAt !== null) {
                $nextPollAt = $record->lastPollAt->getTimestamp() + $record->interval;
                if ($now->getTimestamp() < $nextPollAt) {
                    throw DeviceAuthorizationException::slowDown();
                }
            }
            $this->gateway->touchPoll($deviceCode, $now);
            throw DeviceAuthorizationException::authorizationPending();
        }
        if ($record->auth === null) {
            throw DeviceAuthorizationException::invalidGrant();
        }
        $this->gateway->consume($deviceCode);
        return $record->auth;
    }

    public static function grantType(): string
    {
        return DeviceAuthorizationGrantType::DEVICE_CODE;
    }

    private function generateUserCode(string $tenant): string
    {
        $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        $max = strlen($alphabet) - 1;
        for ($attempt = 0; $attempt < 5; $attempt++) {
            $raw = '';
            for ($i = 0; $i < 8; $i++) {
                $raw .= $alphabet[random_int(0, $max)];
            }
            $userCode = substr($raw, 0, 4) . '-' . substr($raw, 4, 4);
            if ($this->gateway->findByUserCode($tenant, $userCode) === null) {
                return $userCode;
            }
        }
        return Random::uuid();
    }
}
